<?php if($d['image_url']??null): ?><img class="community-image" src="<?= e(url('community-image.php?'.http_build_query(['kind'=>$kind,'id'=>$id,'key'=>basename($d['image_url'])]))) ?>" alt="<?= e($d['image_alt']??$d['name']??'Business image') ?>"><?php endif; ?>
