<div class="community-actions"><?php foreach(['maps_url'=>['Google Maps',['https'],'maps_click'],'website_url'=>['Website',['https','http'],'website_click'],'phone_url'=>['Call business',['tel'],'phone_click'],'email_url'=>['Email business',['mailto'],null]] as $key=>[$label,$schemes,$event]):$href=communitySafeUrl($d[$key]??null,$schemes);if($href):$external=str_starts_with($href,'http'); ?><a class="button button-secondary" href="<?= e($href) ?>"<?= $external?' target="_blank" rel="noopener noreferrer" aria-label="'.e($label).' (opens in a new tab)"':'' ?><?= $event?' data-event="'.e($event).'"':'' ?>><?= e($label) ?></a><?php endif;endforeach; ?></div>
